1	package docker
2	
3	import (
4		"context"
5		"errors"
6		"slices"
7		"strings"
8		"testing"
9	
10		"github.com/anthnel/devdesk/internal/engine"
11	)
12	
13	const testCtrID = "0123456789ab"
14	
15	func TestParseContainerNetworking(t *testing.T) {
16		tests := []struct {
17			name    string
18			in      string
19			wantErr bool
20			check   func(t *testing.T, n ContainerNetworking)
21		}{
22			{
23				name: "one bridge endpoint",
24				in:   `{"Name":"/web-1","Mode":"bridge","Running":true,"Networks":{"bridge":{"IPAddress":"172.17.0.3","Gateway":"172.17.0.1","GwPriority":0,"IPPrefixLen":16}}}`,
25				check: func(t *testing.T, n ContainerNetworking) {
26					if n.Name != "web-1" || n.Mode != "bridge" || !n.Running || len(n.Networks) != 1 {
27						t.Fatalf("got %+v", n)
28					}
29					e := n.Networks[0]
30					if e.Name != "bridge" || !e.IPv4.Is4() || e.IPv4.String() != "172.17.0.3" ||
31						!e.Gateway.Is4() || e.Gateway.String() != "172.17.0.1" {
32						t.Errorf("endpoint = %+v", e)
33					}
34					if e.GwPriority == nil || *e.GwPriority != 0 {
35						t.Errorf("GwPriority = %v, want pointer to 0", e.GwPriority)
36					}
37				},
38			},
39			{
40				name: "GwPriority absent is nil and networks sort by name",
41				in:   `{"Name":"/x","Mode":"z","Running":false,"Networks":{"z":{"IPAddress":"10.0.0.2","Gateway":"10.0.0.1"},"a":{"IPAddress":"10.1.0.2","Gateway":"10.1.0.1"}}}`,
42				check: func(t *testing.T, n ContainerNetworking) {
43					if len(n.Networks) != 2 || n.Networks[0].Name != "a" || n.Networks[1].Name != "z" {
