				t.Errorf("container call %v is not inspect", c.Args)
			}
		default:
			t.Errorf("unexpected subcommand %v", c.Args)
		}
		for _, a := range c.Args {
			if slices.Contains(forbidden, a) {
				t.Errorf("forbidden arg %q in %v", a, c.Args)
			}
		}
	}
}

